gaPi(){return"\u064a\u0645\u0643\u0646 \u0625\u0631\u0641\u0627\u0642 \u062a\u0642\u0631\u064a\u0631 \u0637\u0628\u064a \u0641\u0642\u0637 \u0639\u0646\u062f \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0648\u0638\u0641 \u0648\u0627\u062d\u062f"},
gaP6(){return"\u062a\u0645 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0625\u062c\u0627\u0632\u0629\u060c \u0644\u0643\u0646 \u062a\u0639\u0630\u0631 \u0631\u0641\u0639 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0637\u0628\u064a"},
gb_J(){return"\u064a\u0631\u062c\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062a\u0627\u0631\u064a\u062e"},
gaWZ(){return"\u064a\u062c\u0628 \u0623\u0644\u0627 \u064a\u0643\u0648\u0646 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0646\u0647\u0627\u064a\u0629 \u0642\u0628\u0644 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0628\u062f\u0627\u064a\u0629"},
ga55(){return"\u0646\u0635\u0641 \u0627\u0644\u064a\u0648\u0645"},
