gax2(){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0648\u0642\u062a"},
gaP1(){return"\u0645\u0647\u0627\u0645 \u0639\u0645\u0644 \u062c\u0645\u0627\u0639\u064a\u0629"},
gaPe(){return"\u0628\u0635\u0645\u0627\u062a \u0646\u0627\u0642\u0635\u0629 \u062c\u0645\u0627\u0639\u064a\u0629"},
gaP2(){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 \u0645\u0647\u0627\u0645 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u064a\u0629 \u0628\u0646\u062c\u0627\u062d"},
gaPf(){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0628\u0635\u0645\u0627\u062a \u0627\u0644\u0646\u0627\u0642\u0635\u0629 \u0627\u0644\u062c\u0645\u0627\u0639\u064a\u0629 \u0628\u0646\u062c\u0627\u062d"},
